class Lamp:
    def on(self):
        self.bulb.power(True)

    def off(self):
        self.bulb.power(False)
class Cart:
    def add(self, item):
        self.items.append(item)

    def clear(self):
        self.items = []
def run(jobs):
    for job in jobs:
        job.start()

    print('started')
class Timer:
    def reset(self):
        self.clock.zero()

    def tick(self):
        self.count += 1
def save(rows, db):
    with db.session() as s:
        s.write(rows)

    return len(rows)
class Robot:
    def stop(self):
        self.motor.halt()

    def go(self):
        self.motor.spin(5)
def draw(shapes, canvas):
    for s in shapes:
        canvas.paint(s)

    canvas.flush()
class Door:
    def lock(self):
        self.bolt.slide(1)

    def unlock(self):
        self.bolt.slide(0)
